	// the transformer's prefix and its own share of the prefix KV cache, so
	// the number is fixed when the server starts. Zero when Edits is false.
	MaxRefs int
}

// MaxSquare is the largest square inside the pixel budget, snapped down to
// Multiple. It is what `max_size` reports, because a client that wants one
// number rather than a rule wants this one -- and because a size the server
// is certain to accept is the useful thing to echo back into a request.
func (g ImageGeometry) MaxSquare() (int, int) {
	m := g.Multiple
	if m < 1 {
		m = 1
	}
	side := int(math.Sqrt(float64(g.MaxPixels))) / m * m
	if side < m {
		side = m
	}
	return side, side
}

// MarshalJSON writes the geometry the way a client reads it: the sizes
// spelled as OpenAI spells a size, so one can be echoed straight back into a
// request's `size` without being reassembled first.
//
// `max_pixels` is the rule and `max_size` is the largest square that obeys
// it. Both are reported because a client asking for a square only needs the
// second, and one asking for 16:9 cannot work it out from the second alone.
func (g ImageGeometry) MarshalJSON() ([]byte, error) {
	maxW, maxH := g.MaxSquare()
	return json.Marshal(struct {
		DefaultSize  string `json:"default_size"`
		MaxSize      string `json:"max_size"`
		MaxPixels    int    `json:"max_pixels"`
		SizeMultiple int    `json:"size_multiple"`
		DefaultSteps int    `json:"default_steps"`
		Previews     bool   `json:"previews"`
		MaxPartials  int    `json:"max_partial_images,omitempty"`
		Edits        bool   `json:"edits"`
		MaxRefs      int    `json:"max_reference_images,omitempty"`
	}{
		DefaultSize:  formatSize(g.Width, g.Height),
		MaxSize:      formatSize(maxW, maxH),
		MaxPixels:    g.MaxPixels,
		SizeMultiple: g.Multiple,
		DefaultSteps: g.Steps,
		Previews:     g.Previews,
		MaxPartials:  g.MaxPartials,
		Edits:        g.Edits,
		MaxRefs:      g.MaxRefs,
	})
}

// ErrUnsupported is what a backend returns when a request is well formed but
// asks for something this model cannot do -- an unknown voice, a sample rate
// it does not take. It becomes a 400 rather than a 500, because the client
// can fix it.
var ErrUnsupported = errors.New("unsupported request")

// errorBody is OpenAI's error envelope, which is what every client of this
// API already knows how to read.
type errorBody struct {
	Message string `json:"message"`
	Type    string `json:"type"`
	Code    string `json:"code,omitempty"`
}

type errorResponse struct {
	Error errorBody `json:"error"`
}

// writeError answers with OpenAI's error shape. typ is the coarse class the
// client switches on ("invalid_request_error", "server_error").
func writeError(w http.ResponseWriter, status int, typ, msg string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(errorResponse{Error: errorBody{Message: msg, Type: typ}})
}

// logf is how this package logs anything about a request in flight. It
// carries the access log's request id, without which a line like
// "api: chat completion: context deadline exceeded" cannot be attributed to
// one of the several requests that were in flight when it was written.
func logf(ctx context.Context, format string, args ...any) {
	if id := util.RequestID(ctx); id != "" {
		log.Printf("[%s] api: %s", id, fmt.Sprintf(format, args...))
		return
	}
	log.Printf("api: %s", fmt.Sprintf(format, args...))
}

// badRequest is the client's fault; serverError is ours, and is the one that
// gets logged, because nobody sees the response body of a 500 at 3am.
//
// A 400 is logged too. It is the client's mistake rather than the server's,
// but it is still a request that did not do what whoever sent it wanted, and
// the reason is in the response body where only they can see it.
func badRequest(ctx context.Context, w http.ResponseWriter, msg string) {
	logf(ctx, "400: %s", msg)
	writeError(w, http.StatusBadRequest, "invalid_request_error", msg)
}

func serverError(ctx context.Context, w http.ResponseWriter, where string, err error) {
	logf(ctx, "%s: %v", where, err)
	writeError(w, http.StatusInternalServerError, "server_error", err.Error())
}

// backendError maps a backend's error onto a status. ErrUnsupported is the
// client's fault; anything else is a run that went wrong.
func backendError(ctx context.Context, w http.ResponseWriter, where string, err error) {
	if errors.Is(err, ErrUnsupported) {
		badRequest(ctx, w, err.Error())
		return
	}
	if errors.Is(err, context.Canceled) {
		// The client hung up mid-run. There is nobody to answer.
		logf(ctx, "%s: client cancelled", where)
		return
	}
	serverError(ctx, w, where, err)
}

// notLoaded is the 501 an endpoint gives when the process was started without
// the model behind it. The message names the flag, because the answer to
// "why did this 501" is almost always "it was not asked for on the command
// line".
func notLoaded(ctx context.Context, w http.ResponseWriter, what, flag string) {
	logf(ctx, "501: %s is not loaded (needs %s)", what, flag)
	writeError(w, http.StatusNotImplemented, "not_implemented",
		what+" is not loaded; start the server with "+flag)
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

// tooLarge answers 413 when err is the body cap being hit, and reports
// whether it did. A body over the limit is its own failure and not a
// malformed one: the client can retry with a shorter clip.
func tooLarge(ctx context.Context, w http.ResponseWriter, err error) bool {
	var maxErr *http.MaxBytesError
	if !errors.As(err, &maxErr) {
		return false
	}
	writeError(w, http.StatusRequestEntityTooLarge, "invalid_request_error",
		"the request body is larger than this server's limit of "+
			strconv.FormatInt(maxErr.Limit, 10)+" bytes")
	return true
}

// decodeJSON reads a JSON request body into v, answering the client itself if
// it cannot. It reports whether the handler should carry on.
func decodeJSON(ctx context.Context, w http.ResponseWriter, r *http.Request, v any) bool {
	if err := json.NewDecoder(r.Body).Decode(v); err != nil {
		if tooLarge(ctx, w, err) {
			return false
		}
		badRequest(ctx, w, "malformed JSON body: "+err.Error())
		return false
	}
	return true
}
package api

// POST /v1/systemone (CLASSIFICATION.md K6): TypeSafe's System One contract,
// as Kev serves it. One text (the state) and typed questions in, one
// calibrated probability distribution per question out, in one prefill.
//
// Unlike every other endpoint here the envelope is not OpenAI's, and it is
// not decoded in this package. The request is model-shaped all the way down:
// an object state's key order and a number's int-ness decide the text the
// model reads, and a choice's criteria order decides its option slots, so the
// body crosses the boundary as bytes and the backend parses it with the
// rules the model was trained under. What stays here is the transport: the
// body cap, auth, the request id TypeSafe's clients read, and the status.

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"io"
	"net/http"

	"strix-halo-vulkan/util"
)

// SystemOneBackend answers System One requests.
type SystemOneBackend interface {
	Backend
	// SystemOne parses and answers one request body, returning the response
	// body. An error wrapping ErrUnprocessable is the client's (a 422, as
	// TypeSafe and Kev answer it); anything else is the server's.
	SystemOne(ctx context.Context, body []byte) ([]byte, error)
}

// ErrUnprocessable is a well-formed request the model cannot answer as asked:
// a missing field, an unknown question type, too many options, a branch
// longer than a row.
var ErrUnprocessable = errors.New("unprocessable request")

func (s *Server) handleSystemOne(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	id := r.Header.Get("X-Typesafe-Request-Id")
	if id == "" {
		id = util.RequestID(ctx)
	}
	if id == "" {
		var b [16]byte
		_, _ = rand.Read(b[:])
		id = hex.EncodeToString(b[:])
	}
	w.Header().Set("X-Typesafe-Request-Id", id)

	if s.SystemOne == nil {
		notLoaded(ctx, w, "the classification model", "-kev")
		return
	}
	body, err := io.ReadAll(r.Body)
	if err != nil {
		if tooLarge(ctx, w, err) {
			return
		}
		badRequest(ctx, w, "reading the body: "+err.Error())
		return
	}
	out, err := s.SystemOne.SystemOne(ctx, body)
	if err != nil {
		if errors.Is(err, ErrUnprocessable) {
			logf(ctx, "422: %v", err)
			writeError(w, http.StatusUnprocessableEntity, "invalid_request_error", err.Error())
			return
		}
		if errors.Is(err, context.Canceled) {
			logf(ctx, "systemone: client cancelled")
			return
		}
		serverError(ctx, w, "systemone", err)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(out)
}
package api

import (
	"net/http"
	"sort"
)

type ModelsResponse struct {
	Object string  `json:"object"`
	Data   []Model `json:"data"`
}

// Model represents a single model in the list of models.
type Model struct {
	ID      string `json:"id"`
	Object  string `json:"object"`   // "model"
	OwnedBy string `json:"owned_by"` // "organization_owner"
	// Voices is this model's voice names, for a speech model. It is not part
	// of OpenAI's model object -- clients ignore fields they do not know --
	// and it is here because the alternative is a second round trip to find
	// out what /v1/audio/speech will accept. A request may also name a
	// mixture of these, comma-joined, so the list is the alphabet rather
	// than the set.
	Voices []string `json:"voices,omitempty"`
	// Image is the geometry an image model will accept, and is here for the
	// same reason: the sizes /v1/images/generations takes are decided by what
	// this process staged, so a client that has to guess will guess wrong on
	// a server started at something other than 1024x1024.
	Image *ImageGeometry `json:"image,omitempty"`
}

// backends returns every loaded backend, in the order GET /v1/models lists
// them. A nil field is a model this process was not started with.
func (s *Server) backends() []Backend {
	var out []Backend
	if s.Completion != nil {
		out = append(out, s.Completion)
	}
	if s.Embedding != nil {
		out = append(out, s.Embedding)
	}
	if s.Speech != nil {
		out = append(out, s.Speech)
	}
	if s.Transcription != nil {
		out = append(out, s.Transcription)
	}
	if s.Image != nil {
		out = append(out, s.Image)
	}
	if s.SystemOne != nil {
		out = append(out, s.SystemOne)
	}
	return out
}

// handleModels lists what this process actually loaded, which is the only
// honest answer: a server started without -tts does not have a speech model,
// and saying so here is cheaper for a client than a 501 later.
func (s *Server) handleModels(w http.ResponseWriter, _ *http.Request) {
	resp := ModelsResponse{Object: "list", Data: []Model{}}
	seen := map[string]bool{}
	for _, b := range s.backends() {
		for _, m := range b.Models() {
			if seen[m.ID] {
				continue
			}
			seen[m.ID] = true
			if m.Object == "" {
				m.Object = "model"
			}
			resp.Data = append(resp.Data, m)
		}
	}
	// The presets are models too, as far as a client can tell: each is a
	// name it can put in `model` and get different answers from.
	if s.Completion != nil {
		for _, p := range s.Presets {
			if !seen[p.Name] {
				seen[p.Name] = true
				resp.Data = append(resp.Data, Model{ID: p.Name, Object: "model", OwnedBy: "local"})
			}
		}
	}
	if s.Speech != nil {
		voices := s.Speech.Voices()
		sort.Strings(voices)
		for i := range resp.Data {
			if owns(s.Speech, resp.Data[i].ID) {
				resp.Data[i].Voices = voices
			}
		}
	}
	if s.Image != nil {
		geo := s.Image.Geometry()
		for i := range resp.Data {
			if owns(s.Image, resp.Data[i].ID) {
				g := geo
				resp.Data[i].Image = &g
			}
		}
	}
	writeJSON(w, http.StatusOK, resp)
}

// owns reports whether id is one of this backend's own models, so that the
// voice list and the image geometry land on the models they describe and not
// on whatever else the process loaded beside them.
func owns(b Backend, id string) bool {
	for _, m := range b.Models() {
		if m.ID == id {
			return true
		}
	}
	return false
}

